package com.autoops.dataset.service;import com.autoops.command.entity.CommandDefinition;import com.autoops.command.repository.CommandDefinitionRepository;import com.autoops.command.risk.CommandRiskAnalyzer;import com.autoops.dataset.entity.DatasetImport;import com.autoops.dataset.repository.DatasetImportRepository;import com.autoops.embedding.EmbeddingService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service public class DatasetImportService{private final DatasetImportRepository imports;private final CommandDefinitionRepository commands;private final CommandRiskAnalyzer risk;private final EmbeddingService embeddings;public DatasetImportService(DatasetImportRepository i,CommandDefinitionRepository c,CommandRiskAnalyzer r,EmbeddingService e){imports=i;commands=c;risk=r;embeddings=e;}@Transactional public DatasetImport importRows(Long id,List<Row> rows){var d=imports.findById(id).orElseThrow();d.setStatus("IMPORTING");imports.save(d);Set<String>seen=new HashSet<>();for(Row row:rows){if(row.command()==null||row.command().isBlank()||!seen.add(normalize(row.command())))continue;var c=new CommandDefinition();c.setName(row.name()==null?"Imported Linux action":row.name());c.setDescription(row.description());c.setCategory(row.category());c.setCommandTemplate(row.command());var rr=risk.analyze(row.command());c.setRiskLevel(rr.name());c.setRequiresApproval(rr==CommandRiskAnalyzer.Risk.HIGH);c.setCreatedBy(d.getUploadedBy());c.setSource("DATASET");c.setStatus("PENDING");commands.save(c);embeddings.index(c);}d.setStatus("COMPLETED");return imports.save(d);}private String normalize(String x){return x.trim().replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);}public record Row(String name,String description,String category,String command){}}
